type GuideInput = Omit<Service, "lastVerified" | "sources" | "searchTerms" | "related"> & {
  sources: Source[];
  searchTerms?: string[];
  related?: string[];
};

const guide = (g:GuideInput): Service => ({
  ...g,
  lastVerified: checked,
  searchTerms: g.searchTerms ?? [g.shortTitle, g.title, g.category],
  related: g.related ?? [],
});

const review = (
  slug:string, title:string, shortTitle:string, category:string, agencySlug:string, officialPortal:string, sources:Source[],
): Service => guide({
  slug, title, shortTitle, summary:"This guide is in the verification queue and is not published publicly yet.",
  category, agencySlug, feeLabel:"Review pending", status:"review", officialPortal,
  requirements:["Requirements are being checked against current official sources."],
  steps:["Editorial verification is required before publication."],
  notes:["Review-pending guides are excluded from public search, service directories and sitemaps."],
  sources,
});

